import{_ as o,o as a,c as s,ae as l}from"./chunks/framework.YL6nI5ZP.js";const g=JSON.parse('{"title":"Cómo Desplegar Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/05-desplegar.md","filePath":"es/how-to/05-desplegar.md"}'),i={name:"es/how-to/05-desplegar.md"};function r(d,e,c,t,n,p){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="como-desplegar-local-swmm" tabindex="-1">Cómo Desplegar Local SWMM <a class="header-anchor" href="#como-desplegar-local-swmm" aria-label="Permalink to &quot;Cómo Desplegar Local SWMM&quot;">​</a></h1><p>Despliega la aplicación en un host estático. El sitio de producción es <a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a> (Cloudflare Pages); también existe un workflow de GitHub Pages.</p><p>El wasm del motor 2D está compilado con <strong>pthreads/OpenMP</strong> (<code>scripts/build-openswmm2d.sh</code> / <code>.ps1</code>), por lo que necesita <strong>aislamiento de origen cruzado</strong> — <code>SharedArrayBuffer</code> solo está disponible para páginas servidas con <code>Cross-Origin-Opener-Policy</code> + <code>Cross-Origin-Embedder-Policy</code>. GitHub Pages no permite headers personalizados y no puede servir el build con threads. <strong>Usa Cloudflare Pages.</strong></p><h2 id="_1-despliega-via-cloudflare-pages-recomendado" tabindex="-1">1. Despliega vía Cloudflare Pages (recomendado) <a class="header-anchor" href="#_1-despliega-via-cloudflare-pages-recomendado" aria-label="Permalink to &quot;1. Despliega vía Cloudflare Pages (recomendado)&quot;">​</a></h2><p>Los despliegues ocurren desde <code>.github/workflows/cloudflare.yml</code> al hacer push a <code>main</code> / <code>experimental</code> (el workflow también lista <code>website</code>). Escribe <code>config.js</code> y <code>build-version.js</code> (sello de caché) a partir de secretos, y luego sube <code>public/</code> vía <code>cloudflare/pages-action</code>.</p><p>Configuración (una vez):</p><ol><li>Crea un proyecto Pages (o ejecuta <code>npx wrangler pages deploy public</code> manualmente — se incluye <code>wrangler.toml</code>).</li><li>Agrega los secretos del repositorio: <ul><li><code>CLOUDFLARE_API_TOKEN</code> (un token con permiso <code>Pages:Edit</code>)</li><li><code>CLOUDFLARE_ACCOUNT_ID</code></li><li><code>CLOUDFLARE_PROJECT_NAME</code></li><li>los existentes <code>MAPBOX_ACCESS_TOKEN</code>, <code>GOOGLE_MAPS_API_KEY</code>, <code>OPENTOPOGRAPHY_API_KEY</code></li></ul></li><li>Apunta tu dominio personalizado (<code>swmm6.is-local.org</code>) al proyecto Pages. Los headers <code>Cross-Origin-Opener-Policy: same-origin</code> / <code>Cross-Origin-Embedder-Policy: credentialless</code> vienen de <code>public/_headers</code> (credentialless para que los recursos de Mapbox/Google/OpenTopography carguen sin headers CORP).</li><li>Elimina <code>.github/workflows/static.yml</code> (GitHub Pages) una vez que Cloudflare esté activo.</li></ol><p><code>wrangler.toml</code> (incluido en la raíz del repo) te permite hacer push manualmente:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span></span></code></pre></div><h2 id="_2-despliega-via-github-pages-github-workflows-static-yml" tabindex="-1">2. Despliega vía GitHub Pages (<code>.github/workflows/static.yml</code>) <a class="header-anchor" href="#_2-despliega-via-github-pages-github-workflows-static-yml" aria-label="Permalink to &quot;2. Despliega vía GitHub Pages (`.github/workflows/static.yml`)&quot;">​</a></h2><p><strong>Solo despliegue de GitHub Pages — no hay build de WASM en CI.</strong> El motor se compila localmente en <code>experimental</code> y los artefactos se commitean en <code>public/</code>.</p><p>El workflow hace:</p><ol><li>Disparadores: push a <code>main</code> + <code>experimental</code>, o dispatch manual.</li><li>Checkout (v4, sin <code>submodules: recursive</code> — el wasm precompilado viaja en <code>public/</code>).</li><li><strong>Genera <code>public/config.js</code> a partir de secretos</strong> (<code>MAPBOX_ACCESS_TOKEN</code>, <code>GOOGLE_MAPS_API_KEY</code>, <code>OPENTOPOGRAPHY_API_KEY</code>).</li><li>Sube <code>./public</code> como artefacto de Pages → despliega con <code>actions/deploy-pages@v4</code>.</li></ol><blockquote><p>Nota (desde el archivo del workflow): GitHub Pages no puede configurar headers COOP/COEP, por lo que el wasm 2D con threads (pthreads/SharedArrayBuffer) <strong>NO</strong> correrá en este despliegue. Elimina este workflow una vez que Cloudflare esté activo.</p></blockquote><h2 id="_3-sirve-localmente-para-desarrollo" tabindex="-1">3. Sirve localmente para desarrollo <a class="header-anchor" href="#_3-sirve-localmente-para-desarrollo" aria-label="Permalink to &quot;3. Sirve localmente para desarrollo&quot;">​</a></h2><p><code>python server.py</code> envía los mismos headers COOP/COEP, por lo que el motor con threads funciona en <code>http://127.0.0.1:8080</code> de inmediato. El servidor solo se enlaza a <code>127.0.0.1</code>, sirve <code>&lt;repo&gt;/public</code> en el puerto <strong>8080</strong>, expone <code>GET /api/status</code> (→ <code>{&quot;status&quot;:&quot;running&quot;,&quot;msg&quot;:&quot;3D Map Prototype Server Online&quot;}</code>) y envía <code>Cache-Control: no-store</code> más <code>Access-Control-Allow-Origin: *</code> en OPTIONS + <code>/api/status</code>. Los scripts lo lanzan automáticamente cuando <code>http://127.0.0.1:8080/api/status</code> no es alcanzable.</p>',16)])])}const h=o(i,[["render",r]]);export{g as __pageData,h as default};
